# owner: platform
from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def _pad(cells: List[str], widths: List[int]) -> str:
    padded = [c.ljust(w) for c, w in zip(cells, widths)]
    return "  ".join(padded).rstrip()


def _cells(students: List[Student]) -> List[List[str]]:
    ordered = sorted(students, key=lambda s: s.display_name)
    return [
        [s.display_name, s.section, s.email]
        for s in ordered
    ]


# ---
def contact_rows(students: List[Student]) -> List[str]:
    _check(students)
    cells = _cells(students)
    widths = [max(map(len, col)) for col in zip(*cells)]
    return [_pad(row, widths) for row in cells]

