# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def _student(last, section="A", email="x@e.org"):
    return Student("1", last, "Pat", section, email)


def _pair():
    return [
        _student("Zed", "B", "z@e.org"),
        _student("Li", "A", "li@example.org")
    ]


class ContactRowsTests(unittest.TestCase):
    # ---
    def test_sorted_and_aligned(self):
        rows = contact_rows(_pair())
        self.assertEqual(rows, [
            "Li, Pat   A  li@example.org",
            "Zed, Pat  B  z@e.org"
        ])

    # ---
    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as ctx:
            contact_rows([_student("Li", email=None)])
        self.assertIn("Li, Pat", str(ctx.exception))

    # ---
    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
